import{_ as a,o as i,c as l,a3 as r}from"./chunks/framework.Bh_aNVBG.js";const o="/images/project-admin/image%2056.png",e="/images/project-admin/image%2057.png",d="/images/project-admin/image%2058.png",n="/images/project-admin/image%2059.png",h="/images/project-admin/image%2060.png",s="/images/project-admin/image%2061.png",p="/images/project-admin/image%2062.png",g="/images/project-admin/image%2063.png",c="/images/project-admin/image%2064.png",b="/images/project-admin/image%2065.png",m="/images/project-admin/88f623b6-9864-4553-8ef1-0469f9ca330d.png",_="/images/project-admin/image%2066.png",u="/images/project-admin/%EC%8A%A4%ED%83%AC%ED%94%84_%EB%B3%B4%EC%83%81.png",q="/images/project-admin/image%2067.png",k="/images/project-admin/image%2068.png",x="/images/project-admin/image%2069.png",f="/images/project-admin/image%2070.png",A=JSON.parse('{"title":"7. 스탬프 투어 운영","description":"","frontmatter":{},"headers":[],"relativePath":"project-admin/chapter-7.md","filePath":"project-admin/chapter-7.md"}'),P={name:"project-admin/chapter-7.md"};function R(y,t,Q,j,C,S){return i(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="_7-스탬프-투어-운영" tabindex="-1">7. 스탬프 투어 운영 <a class="header-anchor" href="#_7-스탬프-투어-운영" aria-label="Permalink to &quot;7. 스탬프 투어 운영&quot;">​</a></h1><p>스탬프 투어는 방문객이 축제 및 행사장의 지정된 장소를 방문하고 스탬프를 수집하는 참여형 서비스입니다.</p><p>프로젝트 운영자는 CMS에서 스탬프 코스와 수집 지점을 등록하고, 완주 기준 및 보상 정책 등을 설정할 수 있습니다.</p><p>방문객은 지정된 장소에서 스탬프를 수집하며, 설정된 완주 기준을 달성하면 완주 인증 및 보상 수령 기능을 이용할 수 있습니다.</p><h2 id="_7-1-스탬프-투어-기능-안내" tabindex="-1">7.1. 스탬프 투어 기능 안내 <a class="header-anchor" href="#_7-1-스탬프-투어-기능-안내" aria-label="Permalink to &quot;7.1. 스탬프 투어 기능 안내&quot;">​</a></h2><p>스탬프 투어의 주요 관리 기능은 다음과 같습니다.</p><table tabindex="0"><thead><tr><th>기능</th><th>설명</th></tr></thead><tbody><tr><td>스탬프 코스 관리</td><td>스탬프 투어의 이름, 운영 기간, 완주 조건 등 설정</td></tr><tr><td>스탬프 지점 관리</td><td>방문객이 스탬프를 수집할 장소 등록</td></tr><tr><td>스탬프 인증</td><td>QR 코드 및 인증코드를 통한 스탬프 수집</td></tr><tr><td>완주 인증 카드</td><td>코스 완주 시 제공되는 인증 카드 디자인 설정</td></tr><tr><td>보상 정책 관리</td><td>보상 수령 기간, 횟수 및 일자별 수량 설정</td></tr><tr><td>스탬프 마커 관리</td><td>투어맵에 스탬프 및 코스 위치 표시</td></tr><tr><td>프로모션 관리</td><td>스탬프 투어 관련 홍보 콘텐츠 관리</td></tr></tbody></table><h3 id="스탬프-투어-구성-절차" tabindex="-1">스탬프 투어 구성 절차 <a class="header-anchor" href="#스탬프-투어-구성-절차" aria-label="Permalink to &quot;스탬프 투어 구성 절차&quot;">​</a></h3><ol><li>보상 정책 등록 (보상을 운영하는 경우)</li><li>스탬프 코스 생성</li><li>코스별 스탬프 지점 등록</li><li>완주 기준 및 인증 카드 설정</li><li>QR 코드 및 인증코드 확인</li><li>지도에 스탬프 관련 마커 구성</li><li>프로모션 및 보상 운영</li><li>방문객 화면에서 최종 점검</li></ol><p><img src="'+o+'" alt="image.png"></p><blockquote><p><strong>참고</strong></p><p>스탬프 투어를 사용하려면 프로젝트 설정에서 <strong>스탬프 투어 모듈</strong>이 활성화되어 있어야 합니다.</p><p>모듈 설정 방법은 <strong>3.4. 서비스 모듈 설정</strong>을 참고해 주세요.</p></blockquote><hr><h2 id="_7-2-스탬프-코스-생성-및-관리" tabindex="-1">7.2. 스탬프 코스 생성 및 관리 <a class="header-anchor" href="#_7-2-스탬프-코스-생성-및-관리" aria-label="Permalink to &quot;7.2. 스탬프 코스 생성 및 관리&quot;">​</a></h2><p>스탬프 코스는 여러 개의 스탬프 수집 지점을 하나로 묶어 운영하는 단위입니다.</p><p>하나의 프로젝트에서 행사 목적에 따라 서로 다른 스탬프 코스를 구성할 수 있습니다.</p><p>예를 들어 공연장 탐방 코스, 지역 상점 방문 코스, 체험 프로그램 참여 코스 등으로 구분하여 운영할 수 있습니다.</p><h3 id="_1-스탬프-코스-관리-화면-이동" tabindex="-1">① 스탬프 코스 관리 화면 이동 <a class="header-anchor" href="#_1-스탬프-코스-관리-화면-이동" aria-label="Permalink to &quot;① 스탬프 코스 관리 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>스탬프 코스 관리</strong> 메뉴를 선택합니다.</li><li>등록된 스탬프 코스 목록을 확인합니다.</li><li>새로운 코스를 등록하려면 코스 추가 기능을 선택합니다.</li></ol><p><img src="'+e+'" alt="image.png"></p><h3 id="_2-스탬프-코스-기본-정보-입력" tabindex="-1">② 스탬프 코스 기본 정보 입력 <a class="header-anchor" href="#_2-스탬프-코스-기본-정보-입력" aria-label="Permalink to &quot;② 스탬프 코스 기본 정보 입력&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>코스 명</td><td>방문객에게 표시할 스탬프 코스의 이름</td></tr><tr><td>기간</td><td>스탬프 코스 운영 시작일 및 종료일</td></tr><tr><td>설명</td><td>코스의 주요 내용 및 참여 안내</td></tr><tr><td>대표 이미지</td><td>스탬프 코스를 소개할 이미지</td></tr></tbody></table><p><strong>등록 방법</strong></p><ol><li>코스 등록 화면으로 이동합니다.</li><li><strong>코스 명</strong>을 입력합니다.</li><li>코스의 운영 기간을 설정합니다.</li><li>코스 설명을 입력합니다.</li><li>대표 이미지를 등록합니다.</li><li>나머지 설정 항목을 확인한 후 저장합니다.</li></ol><p><img src="'+d+'" alt="image.png"></p><p><strong>코스 구성 예시</strong></p><table tabindex="0"><thead><tr><th>항목</th><th>설정 예시</th></tr></thead><tbody><tr><td>코스 명</td><td>가을 축제 탐방 코스</td></tr><tr><td>운영 기간</td><td>2026.10.15 ~ 2026.10.18</td></tr><tr><td>설명</td><td>행사장 내 주요 체험 공간을 방문하고 스탬프를 수집해 보세요.</td></tr><tr><td>대표 이미지</td><td>축제 대표 이미지</td></tr></tbody></table><hr><h2 id="_7-3-스탬프-수집-지점-등록" tabindex="-1">7.3. 스탬프 수집 지점 등록 <a class="header-anchor" href="#_7-3-스탬프-수집-지점-등록" aria-label="Permalink to &quot;7.3. 스탬프 수집 지점 등록&quot;">​</a></h2><p>스탬프 지점은 방문객이 지정된 장소에서 인증을 진행하여 스탬프를 수집하는 대상입니다.</p><p>하나의 스탬프 코스에 여러 수집 지점을 등록할 수 있습니다.</p><h3 id="_1-스탬프-지점-추가" tabindex="-1">① 스탬프 지점 추가 <a class="header-anchor" href="#_1-스탬프-지점-추가" aria-label="Permalink to &quot;① 스탬프 지점 추가&quot;">​</a></h3><ol><li><strong>스탬프 코스 관리</strong> 화면으로 이동합니다.</li><li>지점을 추가할 코스를 선택합니다.</li><li>코스의 스탬프 지점 목록을 확인합니다.</li><li><strong>스탬프 스팟 추가</strong> 기능을 선택합니다.</li></ol><p><img src="'+n+'" alt="image.png"></p><h3 id="_2-스탬프-기본-정보-입력" tabindex="-1">② 스탬프 기본 정보 입력 <a class="header-anchor" href="#_2-스탬프-기본-정보-입력" aria-label="Permalink to &quot;② 스탬프 기본 정보 입력&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>스탬프 명</td><td>스탬프 수집 지점의 이름</td></tr><tr><td>관련 콘텐츠</td><td>스탬프 지점과 연결할 상세 콘텐츠</td></tr><tr><td>상시 운영</td><td>운영 기간과 관계없이 상시 운영할지 설정</td></tr><tr><td>운영일자</td><td>스탬프를 수집할 수 있는 운영 기간</td></tr></tbody></table><p><strong>설정 방법</strong></p><ol><li>스탬프 명을 입력합니다.</li><li>필요한 경우 관련 상세 콘텐츠를 연결합니다.</li><li><strong>상시 운영</strong> 여부를 선택합니다.</li><li>상시 운영이 아닌 경우 운영 시작일과 종료일을 설정합니다.</li><li>스탬프 이미지를 등록합니다.</li><li>설정 내용을 저장합니다.</li></ol><p><img src="'+h+'" alt="image.png"></p><h3 id="_3-관련-상세-콘텐츠-연결" tabindex="-1">③ 관련 상세 콘텐츠 연결 <a class="header-anchor" href="#_3-관련-상세-콘텐츠-연결" aria-label="Permalink to &quot;③ 관련 상세 콘텐츠 연결&quot;">​</a></h3><p>스탬프 지점에는 기존에 등록한 상세 콘텐츠를 연결할 수 있습니다.</p><p>이를 통해 방문객이 스탬프 수집 장소와 관련된 프로그램이나 시설 정보를 확인할 수 있습니다.</p><p><strong>설정 방법</strong></p><ol><li>스탬프 지점 편집 화면에서 관련 콘텐츠 영역을 확인합니다.</li><li>등록된 상세 콘텐츠를 검색합니다.</li><li>연결할 콘텐츠를 선택합니다.</li><li>연결 결과를 확인하고 저장합니다.</li></ol><h3 id="_4-스탬프-이미지-설정" tabindex="-1">④ 스탬프 이미지 설정 <a class="header-anchor" href="#_4-스탬프-이미지-설정" aria-label="Permalink to &quot;④ 스탬프 이미지 설정&quot;">​</a></h3><p>스탬프는 수집 여부에 따라 서로 다른 이미지를 사용할 수 있습니다.</p><table tabindex="0"><thead><tr><th>이미지</th><th>설명</th></tr></thead><tbody><tr><td>미수집</td><td>아직 수집하지 않은 스탬프에 표시할 이미지</td></tr><tr><td>수집 완료</td><td>수집이 완료된 스탬프에 표시할 이미지</td></tr></tbody></table><p><strong>설정 방법</strong></p><ol><li>스탬프 이미지 설정 영역으로 이동합니다.</li><li><strong>미수집</strong> 이미지를 등록합니다.</li><li><strong>수집 완료</strong> 이미지를 등록합니다.</li><li>두 이미지가 올바르게 등록되었는지 확인합니다.</li><li>변경 내용을 저장합니다.</li></ol><p><img src="'+s+'" alt="image.png"></p><blockquote><p><strong>참고</strong></p><p>스탬프 이미지의 디자인을 다르게 설정하면 방문객이 수집 상태를 쉽게 구분할 수 있습니다.</p><p>같은 코스에 속한 스탬프는 통일된 디자인을 사용하는 것을 권장합니다.</p></blockquote><hr><h2 id="_7-4-qr-코드-및-인증코드-관리" tabindex="-1">7.4. QR 코드 및 인증코드 관리 <a class="header-anchor" href="#_7-4-qr-코드-및-인증코드-관리" aria-label="Permalink to &quot;7.4. QR 코드 및 인증코드 관리&quot;">​</a></h2><p>스탬프 지점에서는 방문객의 스탬프 수집을 위한 QR 코드와 인증코드를 확인할 수 있습니다.</p><p>QR 코드와 인증코드는 스탬프 지점을 저장한 후 생성된 정보를 조회할 수 있습니다.</p><h3 id="_1-qr-코드-및-인증코드-확인" tabindex="-1">① QR 코드 및 인증코드 확인 <a class="header-anchor" href="#_1-qr-코드-및-인증코드-확인" aria-label="Permalink to &quot;① QR 코드 및 인증코드 확인&quot;">​</a></h3><ol><li>스탬프 지점 등록을 완료합니다.</li><li>저장된 스탬프 지점의 상세 화면으로 이동합니다.</li><li><strong>QR 코드 및 인증코드</strong> 영역을 확인합니다.</li><li>생성된 QR 코드와 인증코드가 올바르게 표시되는지 확인합니다.</li></ol><p><img src="'+p+'" alt="image.png"></p><blockquote><p><strong>참고</strong></p><p>신규 스탬프 지점은 저장을 완료해야 QR 코드와 인증코드를 확인할 수 있습니다.</p></blockquote><h3 id="_2-qr-코드-다운로드" tabindex="-1">② QR 코드 다운로드 <a class="header-anchor" href="#_2-qr-코드-다운로드" aria-label="Permalink to &quot;② QR 코드 다운로드&quot;">​</a></h3><ol><li>스탬프 지점 상세 화면에서 QR 코드를 확인합니다.</li><li>QR 코드 아래의 <strong>다운로드</strong> 버튼을 클릭합니다.</li><li>다운로드한 파일을 확인합니다.</li><li>필요에 따라 행사장 안내물이나 부스에 QR 코드를 배치합니다.</li></ol><h3 id="_3-인증코드-복사" tabindex="-1">③ 인증코드 복사 <a class="header-anchor" href="#_3-인증코드-복사" aria-label="Permalink to &quot;③ 인증코드 복사&quot;">​</a></h3><ol><li>QR 코드 옆에 표시된 인증코드를 확인합니다.</li><li><strong>복사</strong> 버튼을 클릭합니다.</li><li>복사된 인증코드를 필요한 운영 자료에 사용합니다.</li></ol><h3 id="_4-현장-운영-시-유의사항" tabindex="-1">④ 현장 운영 시 유의사항 <a class="header-anchor" href="#_4-현장-운영-시-유의사항" aria-label="Permalink to &quot;④ 현장 운영 시 유의사항&quot;">​</a></h3><ul><li>QR 코드는 방문객이 쉽게 확인할 수 있는 위치에 배치합니다.</li><li>QR 코드가 훼손되거나 잘리지 않도록 인쇄 상태를 확인합니다.</li><li>실제 행사 운영 전에 QR 코드와 인증코드의 정상 동작 여부를 점검합니다.</li><li>인증코드가 불필요하게 외부에 노출되지 않도록 관리합니다.</li></ul><hr><h2 id="_7-5-코스-완주-기준-설정" tabindex="-1">7.5. 코스 완주 기준 설정 <a class="header-anchor" href="#_7-5-코스-완주-기준-설정" aria-label="Permalink to &quot;7.5. 코스 완주 기준 설정&quot;">​</a></h2><p>완주 기준은 방문객이 코스를 완료하기 위해 수집해야 하는 스탬프 개수를 의미합니다.</p><p>스탬프 코스에서는 운영 날짜별로 완주 기준을 설정할 수 있습니다.</p><h3 id="_1-완주-기준-설정-화면-이동" tabindex="-1">① 완주 기준 설정 화면 이동 <a class="header-anchor" href="#_1-완주-기준-설정-화면-이동" aria-label="Permalink to &quot;① 완주 기준 설정 화면 이동&quot;">​</a></h3><ol><li><strong>스탬프 코스 관리</strong>에서 설정할 코스를 선택합니다.</li><li>코스 편집 화면의 <strong>완주 기준</strong> 영역으로 이동합니다.</li><li>날짜별 스탬프 개수 및 완주 기준을 확인합니다.</li></ol><p><img src="'+g+'" alt="image.png"></p><h3 id="_2-날짜별-완주-기준-입력" tabindex="-1">② 날짜별 완주 기준 입력 <a class="header-anchor" href="#_2-날짜별-완주-기준-입력" aria-label="Permalink to &quot;② 날짜별 완주 기준 입력&quot;">​</a></h3><p>스탬프 코스의 운영 기간에 따라 날짜별 완주 기준을 입력할 수 있습니다.</p><p>예를 들어 다음과 같이 설정할 수 있습니다.</p><table tabindex="0"><thead><tr><th>운영 날짜</th><th>전체 스탬프</th><th>완주 기준</th></tr></thead><tbody><tr><td>10월 15일</td><td>5개</td><td>3개</td></tr><tr><td>10월 16일</td><td>5개</td><td>4개</td></tr><tr><td>10월 17일</td><td>5개</td><td>5개</td></tr></tbody></table><p>위 표는 설정 예시입니다. 실제 입력 가능한 완주 기준은 해당 날짜의 필수 및 전체 스탬프 개수에 따라 제한됩니다.</p><h3 id="_3-기준-일괄-적용" tabindex="-1">③ 기준 일괄 적용 <a class="header-anchor" href="#_3-기준-일괄-적용" aria-label="Permalink to &quot;③ 기준 일괄 적용&quot;">​</a></h3><p>여러 날짜에 동일한 완주 기준을 적용하려면 <strong>기준 일괄 적용</strong> 기능을 사용할 수 있습니다.</p><p><strong>설정 방법</strong></p><ol><li>완주 기준 영역에서 <strong>기준 일괄 적용</strong> 입력란을 확인합니다.</li><li>적용할 스탬프 개수를 입력합니다.</li><li><strong>적용</strong> 버튼을 클릭합니다.</li><li>날짜별 기준이 반영되었는지 확인합니다.</li><li>변경 내용을 저장합니다.</li></ol><blockquote><p><strong>주의사항</strong></p><p>완주 기준은 해당 날짜의 필수 스탬프 개수보다 적거나 전체 스탬프 개수보다 많게 설정할 수 없습니다.</p><p>일괄 적용 시에도 날짜별 허용 범위에 맞게 값이 조정될 수 있으므로 적용 후 결과를 확인해 주세요.</p></blockquote><h2 id="_7-6-완주-인증-카드-설정" tabindex="-1">7.6. 완주 인증 카드 설정 <a class="header-anchor" href="#_7-6-완주-인증-카드-설정" aria-label="Permalink to &quot;7.6. 완주 인증 카드 설정&quot;">​</a></h2><p>완주 인증 카드는 방문객이 스탬프 코스의 완주 기준을 달성했을 때 제공되는 인증 카드입니다.</p><p>프로젝트 운영자는 인증 카드에 사용할 배경 이미지와 인증 번호의 접두어를 설정할 수 있습니다.</p><h3 id="_1-완주-인증-카드-설정" tabindex="-1">① 완주 인증 카드 설정 <a class="header-anchor" href="#_1-완주-인증-카드-설정" aria-label="Permalink to &quot;① 완주 인증 카드 설정&quot;">​</a></h3><ol><li><strong>스탬프 코스 관리</strong>에서 코스를 선택합니다.</li><li><strong>완주 인증 카드</strong> 영역으로 이동합니다.</li><li>인증 번호 Prefix를 입력합니다.</li><li>카드에 사용할 배경 이미지를 등록합니다.</li><li>미리보기에서 표시 결과를 확인합니다.</li><li>변경 내용을 저장합니다.</li></ol><p><img src="'+c+'" alt="image.png"></p><h3 id="_2-인증-카드-설정-항목" tabindex="-1">② 인증 카드 설정 항목 <a class="header-anchor" href="#_2-인증-카드-설정-항목" aria-label="Permalink to &quot;② 인증 카드 설정 항목&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>인증 번호 Prefix</td><td>인증 번호 앞에 사용할 영문 대문자 2글자</td></tr><tr><td>배경 이미지</td><td>완주 인증 카드의 배경으로 사용할 이미지</td></tr><tr><td>인증 카드 미리보기</td><td>인증 카드 디자인 확인</td></tr></tbody></table><h3 id="_3-인증-카드-배경-이미지" tabindex="-1">③ 인증 카드 배경 이미지 <a class="header-anchor" href="#_3-인증-카드-배경-이미지" aria-label="Permalink to &quot;③ 인증 카드 배경 이미지&quot;">​</a></h3><p>배경 이미지는 완주 인증 카드의 배경 영역에 채우기 형태로 표시됩니다.</p><p>이미지를 등록한 뒤에는 미리보기에서 주요 이미지나 문구가 잘리지 않는지 확인해 주세요.</p><blockquote><p><strong>참고</strong></p><p>완주 인증 카드의 배경은 방문객에게 제공되는 화면이므로 행사 브랜드에 맞는 이미지를 사용하는 것을 권장합니다.</p></blockquote><hr><h2 id="_7-7-보상-정책-등록-및-관리" tabindex="-1">7.7. 보상 정책 등록 및 관리 <a class="header-anchor" href="#_7-7-보상-정책-등록-및-관리" aria-label="Permalink to &quot;7.7. 보상 정책 등록 및 관리&quot;">​</a></h2><p>보상 정책은 스탬프 코스를 완주한 방문객이 보상을 수령할 수 있는 조건과 수량을 관리하는 기능입니다.</p><p>프로젝트 운영자는 보상 운영 기간, 수령 기준, 날짜별 지급 가능 수량 등을 설정할 수 있습니다.</p><p>보상을 운영하는 경우 코스에 연결할 보상 정책을 먼저 생성하는 것이 좋습니다.</p><h3 id="_1-보상-정책-관리-화면-이동" tabindex="-1">① 보상 정책 관리 화면 이동 <a class="header-anchor" href="#_1-보상-정책-관리-화면-이동" aria-label="Permalink to &quot;① 보상 정책 관리 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>보상 수령 관리</strong> 메뉴를 선택합니다.</li><li>등록된 보상 정책 목록을 확인합니다.</li><li>새로운 정책을 등록하려면 추가 기능을 선택합니다.</li></ol><p><img src="'+b+'" alt="image.png"></p><h3 id="_2-보상-정책-기본-정보-입력" tabindex="-1">② 보상 정책 기본 정보 입력 <a class="header-anchor" href="#_2-보상-정책-기본-정보-입력" aria-label="Permalink to &quot;② 보상 정책 기본 정보 입력&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>정책 명</td><td>보상 정책의 이름</td></tr><tr><td>기간</td><td>보상을 수령할 수 있는 운영 기간</td></tr><tr><td>보상 수령 기준</td><td>여러 코스를 완주한 방문객의 보상 수령 방식</td></tr></tbody></table><p><strong>설정 방법</strong></p><ol><li>보상 정책 등록 화면으로 이동합니다.</li><li><strong>정책 명</strong>을 입력합니다.</li><li>보상 운영 시작일과 종료일을 설정합니다.</li><li>보상 수령 기준을 선택합니다.</li><li>날짜별 수량 등 추가 설정을 진행합니다.</li></ol><p><img src="'+m+'" alt="image.png"></p><h3 id="_3-보상-수령-기준-설정" tabindex="-1">③ 보상 수령 기준 설정 <a class="header-anchor" href="#_3-보상-수령-기준-설정" aria-label="Permalink to &quot;③ 보상 수령 기준 설정&quot;">​</a></h3><p>한 방문객이 여러 코스를 완주했을 때 보상을 수령할 수 있는 기준을 설정합니다.</p><table tabindex="0"><thead><tr><th>구분</th><th>설명</th></tr></thead><tbody><tr><td>코스별 수령</td><td>완주한 코스별로 보상을 수령하도록 설정</td></tr><tr><td>1회 수령</td><td>여러 코스를 완주하더라도 정책 기준에 따라 한 번만 수령하도록 설정</td></tr></tbody></table><p>행사에서 제공할 보상 수량과 운영 방침에 맞는 기준을 선택합니다.</p><h3 id="_4-날짜별-보상-수량-설정" tabindex="-1">④ 날짜별 보상 수량 설정 <a class="header-anchor" href="#_4-날짜별-보상-수량-설정" aria-label="Permalink to &quot;④ 날짜별 보상 수량 설정&quot;">​</a></h3><p>보상을 수령할 수 있는 날짜별 수량을 설정할 수 있습니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>날짜</td><td>보상이 지급되는 운영 날짜</td></tr><tr><td>수량 제한 사용</td><td>해당 날짜의 지급 수량 제한 여부</td></tr><tr><td>제한 수량</td><td>해당 날짜에 지급할 수 있는 보상 수량</td></tr></tbody></table><p><strong>설정 방법</strong></p><ol><li>보상 정책의 날짜별 수량 설정 영역으로 이동합니다.</li><li>수량 제한을 적용할 날짜를 확인합니다.</li><li>필요한 날짜의 수량 제한 기능을 활성화합니다.</li><li>지급할 수량을 입력합니다.</li><li>변경 내용을 저장합니다.</li></ol><p><img src="'+_+'" alt="image.png"></p><blockquote><p><strong>참고</strong></p><p>보상 재고가 제한된 행사라면 실제 준비된 보상 수량에 맞춰 날짜별 지급 수량을 설정하는 것이 좋습니다.</p></blockquote><h3 id="_5-코스와-보상-정책-연결" tabindex="-1">⑤ 코스와 보상 정책 연결 <a class="header-anchor" href="#_5-코스와-보상-정책-연결" aria-label="Permalink to &quot;⑤ 코스와 보상 정책 연결&quot;">​</a></h3><p>등록된 보상 정책은 스탬프 코스에 연결할 수 있습니다.</p><p><strong>설정 방법</strong></p><ol><li><strong>스탬프 코스 관리</strong>에서 보상 정책을 적용할 코스를 선택합니다.</li><li>코스 편집 화면의 <strong>보상 수령 정책</strong> 영역으로 이동합니다.</li><li>등록된 보상 정책 중 사용할 정책을 선택합니다.</li><li>변경 내용을 저장합니다.</li></ol><p><img src="'+u+'" alt="스탬프 보상.png"></p><blockquote><p><strong>참고</strong></p><p>보상 정책 목록이 비어 있다면 먼저 <strong>스탬프 보상 관리</strong> 메뉴에서 정책을 등록해 주세요.</p></blockquote><hr><h2 id="_7-8-스탬프-투어-지도-마커-설정" tabindex="-1">7.8. 스탬프 투어 지도 마커 설정 <a class="header-anchor" href="#_7-8-스탬프-투어-지도-마커-설정" aria-label="Permalink to &quot;7.8. 스탬프 투어 지도 마커 설정&quot;">​</a></h2><p>스탬프 투어에 등록한 지점과 코스는 투어맵에서 방문객이 확인할 수 있도록 지도 표시 요소를 구성할 수 있습니다.</p><p>스탬프 관련 지도 마커는 일반 맞춤형 마커와 구분하여 관리됩니다.</p><h3 id="_1-스탬프-마커-관리-화면-이동" tabindex="-1">① 스탬프 마커 관리 화면 이동 <a class="header-anchor" href="#_1-스탬프-마커-관리-화면-이동" aria-label="Permalink to &quot;① 스탬프 마커 관리 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>스탬프 마커</strong> 관련 관리 메뉴로 이동합니다.</li><li>스탬프 연결하기 또는 보상 수령처 추가 버튼을 눌러 스탬프 맵에 마커를 추가합니다.</li><li>필요한 객체의 표시 위치와 스타일을 설정합니다.</li></ol><p><img src="'+q+'" alt="image.png"></p><h3 id="_2-스탬프-마커-설정" tabindex="-1">② 스탬프 마커 설정 <a class="header-anchor" href="#_2-스탬프-마커-설정" aria-label="Permalink to &quot;② 스탬프 마커 설정&quot;">​</a></h3><p>지도에 표시할 스탬프 지점을 확인하고 방문객이 실제 장소를 찾을 수 있도록 위치를 설정합니다.</p><p><strong>확인 항목</strong></p><ul><li>마커가 올바른 스탬프 지점에 연결되어 있는지</li><li>마커의 위치가 실제 인증 장소와 일치하는지</li><li>지도에서 마커가 정상적으로 표시되는지</li><li>마커를 선택했을 때 의도한 스탬프 정보가 제공되는지</li></ul><h3 id="_3-코스-마커-확인" tabindex="-1">③ 코스 마커 확인 <a class="header-anchor" href="#_3-코스-마커-확인" aria-label="Permalink to &quot;③ 코스 마커 확인&quot;">​</a></h3><p>설정이 완료되면 방문객 화면에서 스탬프 위치가 정확하게 표시되는지 확인합니다.</p><p><img src="'+k+'" alt="image.png"></p><blockquote><p><strong>참고</strong></p><p>일반 지도 마커의 설정 방법은 <strong>6.6. 맞춤형 마커 관리</strong>를 참고해 주세요.</p></blockquote><hr><h2 id="_7-9-스탬프-프로모션-관리" tabindex="-1">7.9. 스탬프 프로모션 관리 <a class="header-anchor" href="#_7-9-스탬프-프로모션-관리" aria-label="Permalink to &quot;7.9. 스탬프 프로모션 관리&quot;">​</a></h2><p>스탬프 프로모션은 방문객에게 스탬프 투어 관련 행사와 참여 정보를 안내하기 위한 기능입니다.</p><p>프로젝트 운영자는 프로모션 콘텐츠를 등록하고 표시 순서 등을 관리할 수 있습니다.</p><h3 id="_1-프로모션-관리-화면-이동" tabindex="-1">① 프로모션 관리 화면 이동 <a class="header-anchor" href="#_1-프로모션-관리-화면-이동" aria-label="Permalink to &quot;① 프로모션 관리 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>프로모션 관리</strong> 메뉴를 선택합니다.</li><li>등록된 프로모션 목록을 확인합니다.</li><li>필요한 프로모션을 추가하거나 수정합니다.</li></ol><p><img src="'+x+'" alt="image.png"></p><h3 id="_2-프로모션-등록-및-관리" tabindex="-1">② 프로모션 등록 및 관리 <a class="header-anchor" href="#_2-프로모션-등록-및-관리" aria-label="Permalink to &quot;② 프로모션 등록 및 관리&quot;">​</a></h3><ol><li>프로모션 등록 기능을 선택합니다.</li><li>필요한 이미지와 연결 정보를 설정합니다.</li><li>등록된 프로모션을 확인합니다.</li><li>필요한 경우 프로모션 표시 순서를 변경합니다.</li><li>설정을 저장합니다.</li></ol><blockquote><p><strong>참고</strong></p><p>프로모션을 등록한 후에는 방문객 화면에서 이미지와 연결 정보가 정상적으로 표시되는지 확인해 주세요.</p></blockquote><hr><h2 id="_7-10-스탬프-보상-지급-및-관리" tabindex="-1">7.10. 스탬프 보상 지급 및 관리 <a class="header-anchor" href="#_7-10-스탬프-보상-지급-및-관리" aria-label="Permalink to &quot;7.10. 스탬프 보상 지급 및 관리&quot;">​</a></h2><p>스탬프 투어의 보상 지급은 별도로 제공되는 <strong>협력업체(파트너)용 보상 지급 페이지</strong>에서 진행합니다.</p><p>프로젝트 운영자는 CMS에서 보상 정책과 지급 조건을 설정하고, 현장 담당자는 보상 지급 페이지를 통해 방문객의 완주 여부와 보상 수령 상태를 확인하여 보상을 지급합니다.</p><h3 id="_1-보상-지급-운영-방식" tabindex="-1">① 보상 지급 운영 방식 <a class="header-anchor" href="#_1-보상-지급-운영-방식" aria-label="Permalink to &quot;① 보상 지급 운영 방식&quot;">​</a></h3><table tabindex="0"><thead><tr><th>구분</th><th>역할</th></tr></thead><tbody><tr><td>CMS 관리자</td><td>보상 정책, 운영 기간, 수량 제한 및 수령 기준 설정</td></tr><tr><td>현장 보상 담당자</td><td>방문객의 보상 수령 자격 확인 및 지급 처리</td></tr><tr><td>방문객</td><td>스탬프 코스 완주 후 보상 수령</td></tr></tbody></table><h3 id="_2-보상-지급-페이지-접속" tabindex="-1">② 보상 지급 페이지 접속 <a class="header-anchor" href="#_2-보상-지급-페이지-접속" aria-label="Permalink to &quot;② 보상 지급 페이지 접속&quot;">​</a></h3><ol><li>안내받은 <strong>보상 지급 페이지</strong>에 접속합니다.</li><li>협력업체 담당자 계정으로 로그인합니다.</li><li>담당 프로젝트의 보상 지급 화면으로 이동합니다.</li></ol><h3 id="_3-방문객-보상-수령-확인" tabindex="-1">③ 방문객 보상 수령 확인 <a class="header-anchor" href="#_3-방문객-보상-수령-확인" aria-label="Permalink to &quot;③ 방문객 보상 수령 확인&quot;">​</a></h3><p>방문객이 스탬프 코스를 완주하고 보상 수령을 요청하면 현장 담당자는 지급 페이지에서 수령 자격을 확인합니다.</p><p><strong>진행 절차</strong></p><ol><li>방문객에게 완주 인증 정보를 요청합니다.</li><li>보상 지급 페이지에서 인증 정보를 확인합니다.</li><li>방문객의 완주 및 보상 수령 가능 상태를 확인합니다.</li><li>지급 가능한 상태라면 준비된 보상을 제공합니다.</li><li>보상 지급을 완료 처리합니다.</li></ol><p><img src="'+f+'" alt="image.png"></p><h3 id="_4-보상-지급-시-유의사항" tabindex="-1">④ 보상 지급 시 유의사항 <a class="header-anchor" href="#_4-보상-지급-시-유의사항" aria-label="Permalink to &quot;④ 보상 지급 시 유의사항&quot;">​</a></h3><ul><li>방문객의 보상 수령 자격을 확인한 후 지급합니다.</li><li>이미 보상을 수령한 방문객에게 중복 지급되지 않도록 확인합니다.</li><li>날짜별 보상 수량 제한이 설정된 경우 남은 수량을 확인합니다.</li><li>보상 지급을 완료한 경우 시스템에서 정상적으로 처리되었는지 확인합니다.</li><li>지급 과정에서 문제가 발생하면 프로젝트 운영 담당자에게 문의합니다.</li></ul><blockquote><p><strong>주의사항</strong></p><p>보상 정책과 지급 조건은 CMS에서 관리하지만, 실제 보상 지급 처리는 협력업체용 페이지에서 진행합니다.</p><p>따라서 현장 담당자에게는 행사 시작 전에 보상 지급 페이지 접속 방법과 지급 절차를 별도로 안내해 주세요.</p></blockquote><h3 id="_5-보상-운영-종료" tabindex="-1">⑤ 보상 운영 종료 <a class="header-anchor" href="#_5-보상-운영-종료" aria-label="Permalink to &quot;⑤ 보상 운영 종료&quot;">​</a></h3><p>행사 종료 후에는 보상 정책의 운영 기간과 지급 상태를 확인합니다.</p><p>필요한 경우 보상 정책을 정리하고, 현장 보상 지급 담당자에게 운영 종료 사실을 안내합니다.</p><hr><h2 id="_7-11-스탬프-투어-운영-점검" tabindex="-1">7.11. 스탬프 투어 운영 점검 <a class="header-anchor" href="#_7-11-스탬프-투어-운영-점검" aria-label="Permalink to &quot;7.11. 스탬프 투어 운영 점검&quot;">​</a></h2><p>스탬프 투어 설정이 완료되면 방문객용 안내 페이지에서 참여 과정을 점검합니다.</p><h3 id="_1-참여-화면-확인" tabindex="-1">① 참여 화면 확인 <a class="header-anchor" href="#_1-참여-화면-확인" aria-label="Permalink to &quot;① 참여 화면 확인&quot;">​</a></h3><ol><li>방문객용 안내 페이지에 접속합니다.</li><li><strong>스탬프 투어</strong> 메뉴로 이동합니다.</li><li>등록한 코스와 스탬프 지점이 표시되는지 확인합니다.</li><li>QR 코드 및 인증코드를 이용한 수집 기능을 점검합니다.</li><li>완주 기준과 인증 카드 표시 상태를 확인합니다.</li><li>보상을 운영하는 경우 보상 수령 절차도 점검합니다.</li></ol><h3 id="_2-최종-점검-항목" tabindex="-1">② 최종 점검 항목 <a class="header-anchor" href="#_2-최종-점검-항목" aria-label="Permalink to &quot;② 최종 점검 항목&quot;">​</a></h3><ul><li>스탬프 투어 모듈이 활성화되어 있는지 확인</li><li>스탬프 코스의 이름과 기간이 정확한지 확인</li><li>스탬프 지점이 모두 등록되어 있는지 확인</li><li>스탬프 운영일자가 올바르게 설정되어 있는지 확인</li><li>미수집 및 수집 완료 이미지가 정상적으로 표시되는지 확인</li><li>QR 코드와 인증코드가 생성되어 있는지 확인</li><li>날짜별 완주 기준이 올바르게 설정되어 있는지 확인</li><li>완주 인증 카드가 정상적으로 표시되는지 확인</li><li>보상 정책과 코스가 올바르게 연결되어 있는지 확인</li><li>날짜별 보상 수량이 정확하게 설정되어 있는지 확인</li><li>스탬프 관련 지도 마커가 정상적으로 표시되는지 확인</li><li>모바일 환경에서 스탬프 수집 기능이 정상적으로 동작하는지 확인</li></ul>',174)])])}const T=a(P,[["render",R]]);export{A as __pageData,T as default};
